		{"negative rate", -1, 1, newFakeClock(time.Unix(0, 0)), ErrNonPositiveRate},
		{"zero burst", 1, 0, newFakeClock(time.Unix(0, 0)), ErrNonPositiveBurst},
		{"negative burst", 1, -5, newFakeClock(time.Unix(0, 0)), ErrNonPositiveBurst},
		{"nil clock", 1, 1, nil, ErrNilClock},
		{"valid", 10, 5, newFakeClock(time.Unix(0, 0)), nil},
