}

func mustNew(t *testing.T, rate float64, burst int, c Clock) *Limiter {
	t.Helper()
	l, err := NewWithClock(rate, burst, c)
	if err != nil {
		t.Fatalf("NewWithClock(%v, %d): %v", rate, burst, err)
	}
	return l
}

func TestNewValidation(t *testing.T) {
	cases := []struct {
		name    string
		rate    float64
		burst   int
		wantErr bool
	}{
		{"valid", 1, 1, false},
		{"zero rate", 0, 1, true},
		{"negative rate", -1, 1, true},
		{"zero burst", 1, 0, true},
		{"negative burst", 1, -1, true},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			_, err := NewWithClock(tc.rate, tc.burst, &fakeClock{})
			if (err != nil) != tc.wantErr {
				t.Fatalf("err = %v, wantErr = %v", err, tc.wantErr)
			}
		})
	}
	t.Run("nil clock", func(t *testing.T) {
		if _, err := NewWithClock(1, 1, nil); err == nil {
			t.Fatal("expected error for nil clock")
		}
	})
}

func TestAllowN(t *testing.T) {
	start := time.Date(2024, 1, 1, 0, 0, 0, 0, time.UTC)
	cases := []struct {
		name  string
		rate  float64
		burst int
		steps []struct {
			advance time.Duration
			n       int
			want    bool
		}
	}{
		{
			name: "burst consumed immediately", rate: 1, burst: 3,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, 3, true},
				{0, 1, false},
			},
		},
		{
			name: "refill over time", rate: 1, burst: 2,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, 2, true},
				{time.Second, 1, true},
				{0, 1, false},
				{time.Second, 1, true},
			},
		},
		{
			name: "cap at burst", rate: 10, burst: 2,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, 2, true},
				{10 * time.Second, 2, true}, // refilled to burst, not more
				{0, 1, false},
			},
		},
		{
			name: "fractional refill", rate: 2, burst: 1,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, 1, true},
				{250 * time.Millisecond, 1, false}, // 0.5 tokens
				{250 * time.Millisecond, 1, true},  // 1.0 tokens
			},
		},
